update modules set pip_name = $t$plr-ivoryos[usb]==1.0.0b2$t$, module_name = $t$Vantage$t$, module_path = $t$plr_ivoryos.legacy$t$, init_args = $j$[{"name": "simulated", "type": "bool", "default": true}, {"name": "worktable", "type": "str", "default": "worktable.json"}, {"name": "device_address", "type": "int"}, {"name": "serial_number", "type": "str"}, {"name": "channels", "type": "int", "default": 8}, {"name": "step_delay_s", "type": "float", "default": 0}]$j$::jsonb, schema = (select s->$t$Vantage$t$ from _schemas), schema_source = 'introspection', updated_at = now(), description = $t$A Hamilton Vantage (1.3 m deck) through PyLabRobot. PyLabRobot 1.0 drives this robot only through pylabrobot.legacy, so it is one instrument with every LiquidHandler operation (pick_up_tips, aspirate, dispense, move_plate, ...), PyLabRobot's names and arguments; wells are written as PyLabRobot writes them (assay_plate[A1:H1]). Simulated (the default) is PyLabRobot's legacy chatterbox: its tip and volume tracking, not the robot's firmware. Beta: pinned to PyLabRobot 1.0.0b1, run in simulation only. For the real one on USB, untick simulated. Decks on one computer share one Python environment, so this replaces the PyLabRobot that any older plr-ivoryos driver there needs. Add the Labware plugin after this driver to see and edit the worktable.$t$ where id = 185;

insert into module_versions (module_id, version, pip_name, requires, channel, notes, is_current)
select 185, '0.2', $t$plr-ivoryos[usb]>=0.2.0,<1$t$, '{"pylabrobot": "<1"}'::jsonb, 'stable',
  'plr-ivoryos 0.2 on PyLabRobot 0.x: LiquidHandler(backend=..., deck_json=...). Workflows made with it need redoing on 1.0.', false
where not exists (select 1 from module_versions where module_id = 185 and version = '0.2');

update module_versions set is_current = false where module_id = 185;

