update modules set pip_name = $t$plr-ivoryos==1.0.0b2$t$, module_name = $t$LiquidHandler$t$, module_path = $t$plr_ivoryos.legacy$t$, init_args = $j$[{"name": "simulated", "type": "bool", "default": true}, {"name": "channels", "type": "int", "default": 8}, {"name": "deck_type", "type": "str", "default": "STARLetDeck"}, {"name": "worktable", "type": "str", "default": "worktable.json"}, {"name": "step_delay_s", "type": "float", "default": 0}]$j$::jsonb, schema = (select s->$t$LiquidHandler$t$ from _schemas), schema_source = 'introspection', updated_at = now(), description = $t$PyLabRobot's simulated liquid handler (the legacy chatterbox) on any worktable (deck_type: STARLetDeck, STARDeck, OTDeck, NimbusDeck, EVO150Deck, ...): one instrument with every LiquidHandler operation, PyLabRobot's names and arguments, wells written as assay_plate[A1:H1]. For a specific robot, its own driver (Hamilton STAR, Opentrons OT-2, ...) simulates it better. Beta: pinned to PyLabRobot 1.0.0b1. Decks on one computer share one Python environment, so this replaces the PyLabRobot that any older plr-ivoryos driver there needs. Add the Labware plugin after this driver to see and edit the worktable.$t$ where id = 177;

