update plugins set pip_name = $t$plr-ivoryos==1.0.0b2$t$,
  module_ids = array[422, 183, 178, 184, 185, 186, 177, (select id from modules where module_path = 'plr_ivoryos.hamilton' and module_name = 'Prep')]::int[],
  description = $t$Any plr-ivoryos liquid handler's worktable (Opentrons Flex and OT-2, Hamilton STAR, Prep, Nimbus and Vantage, Tecan EVO), drawn live beside every page: what each well holds, which tips are left, and the wells a step is working on. Edit layout to build it: drag labware from PyLabRobot's catalogue onto slots or carriers, fill wells with a liquid, or import a layout you already have; on a Flex, also choose what is mounted. Saved as plr-ivoryos's worktable.json. Add the liquid handler's driver to the deck first: this plugin installs with its PyLabRobot.$t$
where id = 7;

commit;
